import org.junit.jupiter.api.Test;

class LmdbNativeKernelDistinctProofTest {

	@Test
	void lexicalContainerCarriesTheLeftKeyToTheActualOutputPosition() {
		Node lexical = lexicalJoin(2, 3);
		Node suffix = new LeftGroup(List.of(new Probe(0, Operand.col(0), 4)));
		assertEquals(2, certifiedOutput(List.of(lexical, suffix), true, 4, 1, 0));
		assertEquals(-1, certifiedOutput(List.of(lexical, suffix), true, 4, 1));
	}

	@Test
	void lexicalResetAndRightHandWriteInvalidateTheKey() {
		assertEquals(-1, certifiedOutput(List.of(lexicalJoin(0, 3)), true, 0, 1));
		assertEquals(-1, certifiedOutput(List.of(lexicalJoin(2, 0)), true, 0, 1));
	}

	@Test
	void aUnionCannotCertifyThatItsBranchesHaveDisjointKeys() {
		Node union = new Union(List.of(List.of(root()), List.of(root())));
		assertEquals(-1, certifiedOutput(List.of(union), true, 0, 1));
	}

	@Test
	void aLaterBindingOrAnUnsupportedViewInvalidatesTheKey() {
		Node rebind = new BindAlias(Operand.col(1), 0);
		assertEquals(-1, certifiedOutput(List.of(root(), rebind), true, 0, 1));
		assertEquals(-1, certifiedOutput(List.of(root()), false, 0, 1));
	}

	@Test
	void batchedProbeKeepsTheDistinctRootDomainGrouping() {
		Node batched = new SipKeyProbe(0, 0, 0, 1, -1, null, false);
		assertEquals(1, certifiedOutput(List.of(batched), true, 1, 0));
	}

	@Test
	void aliasedProducerRegistersDoNotCertifyTheRoot() {
		assertEquals(-1, certifiedOutput(List.of(new EnumerateAdjKeys(0, 0, 0)), true, 0));
		assertEquals(-1, certifiedOutput(List.of(new EnumerateAdjKeys(0, 0, 1, 0, null, false)), true, 0, 1));
		assertEquals(-1, certifiedOutput(List.of(new SipKeyProbe(0, 0, 0, 0, -1, null, false)), true, 0));
		assertEquals(-1, certifiedOutput(List.of(new SipKeyProbe(0, 0, 0, 1, 0, null, false)), true, 0, 1));
	}

	private static Node root() {
		return new EnumerateAdjKeys(0, 0, 1);
	}

	private static Node lexicalJoin(int problemColumn, int rightColumn) {
		return new LexicalFrameLeftJoin(List.of(root()), List.of(new Probe(0, Operand.col(1), rightColumn)),
				new int[] { problemColumn });
	}

	private static int certifiedOutput(List<Node> pipeline, boolean enumeratesKeys, int... emitColumns) {
		Kernel kernel = new Kernel(5, pipeline, new Emit(emitColumns, false, OutputMods.none()));
		LmdbNativeKernelInterpreter execution = LmdbNativeKernelInterpreter.forRows(kernel, null);
		assertNotNull(execution);
		NativeAdjacency adjacency = mock(NativeAdjacency.class);
		when(adjacency.supportsKeyEnumeration()).thenReturn(enumeratesKeys);
		try {
			execution.bind(new KernelContext(new NativeAdjacency[] { adjacency }, new long[0], new long[0],
					new long[0][]));
			return execution.contiguousDistinctOutput();
		} finally {
			execution.close();
		}
	}
}
